<?php
declare(strict_types=1);require_once __DIR__.'/operations.php';require_role('owner_admin');$service=new \Hambelela\EPI\BookkeepingPerformance(db());$filters=['period'=>(string)($_GET['period']??'previous_month'),'date_from'=>(string)($_GET['date_from']??''),'date_to'=>(string)($_GET['date_to']??''),'employee_id'=>(string)($_GET['employee_id']??''),'match_status'=>(string)($_GET['match_status']??''),'on_time'=>(string)($_GET['on_time']??'')];$summary=$service->getSummary($filters);$orders=$service->getOrderReconciliation($filters);$daily=$service->getDailyReconciliation($filters);$deposits=$service->getDepositPerformance($filters);$timeline=$service->getTimeline($filters);$employees=$service->employeeOptions();$pageTitle='EPI Bookkeeping Verification | '.APP_NAME;$activeApp='kpi';include BASE_PATH.'/shared/header.php';include BASE_PATH.'/shared/sidebar.php';function epi6v($v):string{return$v===null?'Insufficient historical data':htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function epi6money($c):string{return'N$'.number_format(((int)$c)/100,2);}
?>
<main class="workspace module epi-page"><section class="module-header"><div><p class="eyebrow">Employee Performance Intelligence &middot; Phase 6 verification</p><h1>Bookkeeping &amp; Cash Control Performance</h1><p>Owner-only reconciliation evidence. No final employee scores, bonus points or deductions are calculated.</p></div></section>
<form method="get" class="section-card epi6-filters"><label>Employee<select name="employee_id"><option value="">All employees</option><?php foreach($employees as$e):?><option value="<?=(int)$e['id']?>" <?=(string)$e['id']===$filters['employee_id']?'selected':''?>><?=htmlspecialchars((string)$e['full_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Period<select name="period"><?php foreach(['today'=>'Today','yesterday'=>'Yesterday','this_week'=>'This Week','last_week'=>'Last Week','this_month'=>'This Month','previous_month'=>'Previous Month','quarter'=>'Quarter','year'=>'Year','custom'=>'Custom']as$v=>$l):?><option value="<?=$v?>" <?=$filters['period']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>From<input type="date" name="date_from" value="<?=htmlspecialchars($filters['date_from'],ENT_QUOTES,'UTF-8')?>"></label><label>To<input type="date" name="date_to" value="<?=htmlspecialchars($filters['date_to'],ENT_QUOTES,'UTF-8')?>"></label><label>Match status<select name="match_status"><option value="">All</option><?php foreach(['exact_match','amount_mismatch','duplicate_bookkeeping_entry','missing_bookkeeping_entry','partial_match']as$v):?><option value="<?=$v?>"><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></label><button class="btn-primary">Apply</button></form>
<section class="epi6-grid"><article class="section-card"><h2>Order reconciliation</h2><p>Eligible: <?=epi6v($summary['order_reconciliation']['eligible_cash_orders'])?> &middot; Exact: <?=epi6v($summary['order_reconciliation']['exact_matches'])?> &middot; Missing: <?=epi6v($summary['order_reconciliation']['missing_entries'])?> &middot; Mismatches: <?=epi6v($summary['order_reconciliation']['amount_mismatches'])?> &middot; Duplicates: <?=epi6v($summary['order_reconciliation']['duplicate_entries'])?></p><a href="#order-evidence">View Evidence</a></article><article class="section-card"><h2>Cash-entry timing</h2><p>Average: <?=epi6v($summary['cash_entry_timing']['average'])?> &middot; Median: <?=epi6v($summary['cash_entry_timing']['median'])?> business minutes &middot; Same-day: <?=epi6v($summary['cash_entry_timing']['same_day'])?> &middot; Late: <?=epi6v($summary['cash_entry_timing']['late'])?></p><a href="#order-evidence">View Evidence</a></article><article class="section-card"><h2>Daily controls &amp; variance</h2><p>Fully reconciled: <?=epi6v($summary['daily_controls']['fully_reconciled'])?> &middot; Unreconciled: <?=epi6v($summary['daily_controls']['unreconciled'])?> &middot; Shortages: <?=epi6money($summary['daily_controls']['shortage_cents'])?> &middot; Overages: <?=epi6money($summary['daily_controls']['overage_cents'])?></p><a href="#daily-evidence">View Evidence</a></article><article class="section-card"><h2>Deposits</h2><p>Logged: <?=epi6v($summary['deposits']['deposits_logged'])?> &middot; On time: <?=epi6v($summary['deposits']['on_time'])?> &middot; Late: <?=epi6v($summary['deposits']['late'])?>. Timing remains unmeasured until a deadline is configured.</p><a href="#deposit-evidence">View Evidence</a></article><article class="section-card"><h2>Current unresolved risk</h2><p>Cash orders not entered: <?=epi6v($summary['current_risk']['cash_orders_not_entered'])?> &middot; Unreconciled days: <?=epi6v($summary['current_risk']['unreconciled_days'])?> &middot; Financial value: <?=epi6money($summary['current_risk']['total_unresolved_financial_value_cents'])?></p></article></section>
<section id="order-evidence" class="section-card epi6-table"><h2>Order-to-Bookkeeping evidence</h2><table class="ops-table"><thead><tr><th>Business Date</th><th>Order</th><th>Customer</th><th>Cash Component</th><th>Entry</th><th>Actual</th><th>Variance</th><th>Created By</th><th>Delay</th><th>Match</th><th>Evidence</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="11">No eligible cash-order evidence exists for this filter.</td></tr><?php else:foreach($orders as$r):?><tr><td><?=epi6v($r['business_date'])?></td><td><?=epi6v($r['order_number'])?></td><td><?=epi6v($r['customer'])?></td><td><?=epi6money($r['cash_component_cents'])?></td><td><?=epi6v($r['bookkeeping_entry_id'])?></td><td><?=epi6money($r['bookkeeping_cents'])?></td><td><?=epi6money($r['variance_cents'])?></td><td><?=epi6v($r['created_by'])?></td><td><?=epi6v($r['business_minutes'])?></td><td><?=epi6v($r['match_status'])?></td><td><?=epi6v($r['evidence_quality'])?></td></tr><?php endforeach;endif;?></tbody></table></section>
<section id="daily-evidence" class="section-card epi6-table"><h2>Daily reconciliation</h2><table class="ops-table"><thead><tr><th>Date</th><th>Opening</th><th>Cash In</th><th>Cash Out</th><th>Expected Closing</th><th>Actual Closing</th><th>Variance</th><th>Status</th></tr></thead><tbody><?php foreach($daily as$r):?><tr><td><?=epi6v($r['business_date'])?></td><td><?=epi6money($r['opening_cents'])?></td><td><?=epi6money($r['cash_in_cents'])?></td><td><?=epi6money($r['cash_out_cents'])?></td><td><?=epi6money($r['expected_closing_cents'])?></td><td><?=$r['actual_closing_cents']===null?'Insufficient historical data':epi6money($r['actual_closing_cents'])?></td><td><?=epi6money($r['variance_cents'])?></td><td><?=epi6v($r['status'])?></td></tr><?php endforeach;?></tbody></table></section>
<section id="deposit-evidence" class="section-card epi6-table"><h2>Deposit evidence</h2><p><?=count($deposits['rows'])?> deposit-like ledger records found. Missing/late status is not inferred when the configured deadline or evidence is unavailable.</p></section><section class="section-card epi6-table"><h2>Bookkeeping activity timeline</h2><table class="ops-table"><thead><tr><th>Timestamp</th><th>Employee</th><th>Record</th><th>Event</th><th>Previous</th><th>New</th><th>Evidence ID</th></tr></thead><tbody><?php if(!$timeline):?><tr><td colspan="7">No EPI Bookkeeping activity exists for this filter.</td></tr><?php else:foreach($timeline as$r):?><tr><td><?=epi6v($r['occurred_at'])?></td><td><?=epi6v($r['employee_name'])?></td><td><?=epi6v($r['reference_number'])?></td><td><?=epi6v($r['activity_type'])?></td><td><?=epi6v($r['previous_value'])?></td><td><?=epi6v($r['new_value'])?></td><td><?=epi6v($r['activity_uuid'])?></td></tr><?php endforeach;endif;?></tbody></table></section></main>
